import type {
  Cart, CartBuyer, CartLineItem, CartOrigin, CartQuote, CartStatus, CheckoutAcceptance, CreatedCart, ReorderedCart,
  CheckoutCartParams, CreateCartParams, UpdateCartParams, FindCartsParams, QuoteCartParams, QuotePurchaseParams,
  StorefrontUpdateCartParams, StorefrontAddCartProductParams, StorefrontCurrentCartParams, StorefrontCreateCartParams,
  StorefrontCheckoutCartInput, StorefrontQuoteCartParams, StorefrontReorderParams, CartCheckoutRequest,
  CartPresentationChangedError, CartCatalogChoice, CheckoutPaymentChoice, QuoteMoney, QuoteBlocker,
  QuoteShippingOffer, StorefrontClient, EpochMilliseconds,
} from "arky-sdk";
import type { ArkyCartCheckoutInput } from "arky-sdk/storefront";
import type * as Public from "arky-sdk/types";
import type { createAdmin } from "arky-sdk/admin";

type Assert<T extends true> = T;
type Equal<A, B> = (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
type Missing<T, K extends PropertyKey> = K extends keyof T ? false : true;
type RequiredNullable<T, K extends keyof T> = {} extends Pick<T, K> ? false : null extends T[K] ? true : false;
type RequiredField<T, K extends keyof T> = {} extends Pick<T, K> ? false : true;
type AdminCart = ReturnType<typeof createAdmin>["eshop"]["cart"];
type StorefrontCart = StorefrontClient["eshop"]["cart"];

export type CartContracts = [
  Assert<Equal<Cart, Public.Cart>>,
  Assert<Equal<CartStatus, Public.CartStatus>>,
  Assert<Equal<CartStatus["type"], "active" | "abandoned" | "converted" | "merged" | "expired" | "superseded">>,
  Assert<Equal<Extract<CartStatus, { type: "merged" }>, { type: "merged"; target_cart_id: string }>>,
  Assert<Equal<Cart["origin"], CartOrigin>>,
  Assert<Equal<CartOrigin["type"], "storefront" | "reorder" | "account">>,
  Assert<Equal<Cart["line_items"], CartLineItem[]>>,
  Assert<Equal<CartLineItem["type"], "product" | "booking" | "subscription_plan">>,
  Assert<Equal<Cart["buyer"], CartBuyer>>,
  Assert<RequiredField<Cart, "customer_id">>,
  Assert<RequiredNullable<Cart, "offer">>,
  Assert<Equal<Cart["catalog_id"], string>>,
  Assert<Equal<Cart["sales_channel_id"], string>>,
  Assert<Missing<Cart, "market_id">>,
  Assert<Missing<Cart, "company">>,
  Assert<Missing<Cart, "first_order_terms">>,
  Assert<Equal<CreatedCart, Public.CreatedCart>>,
  Assert<Equal<CreatedCart["type"], "created" | "existing">>,
  Assert<Equal<Extract<CreatedCart, { type: "created" }>["recovery_token"], string>>,
  Assert<Missing<Extract<CreatedCart, { type: "existing" }>, "recovery_token">>,
  Assert<Equal<ReorderedCart["cart"], CreatedCart>>,
  Assert<Equal<Awaited<ReturnType<StorefrontCart["create"]>>, CreatedCart>>,
  Assert<Equal<Awaited<ReturnType<StorefrontCart["reorder"]>>, ReorderedCart>>,
  Assert<Equal<Awaited<ReturnType<StorefrontCart["current"]>>, Cart | null>>,
  Assert<Equal<keyof StorefrontCreateCartParams, "id" | "buyer" | "catalog_id">>,
  Assert<Equal<StorefrontCreateCartParams["catalog_id"], string | null>>,
  Assert<Equal<keyof StorefrontReorderParams, "id" | "order_id" | "buyer">>,
  Assert<Equal<keyof StorefrontCurrentCartParams, "buyer" | "catalog_id">>,
  Assert<RequiredField<CreateCartParams, "id">>,
  Assert<RequiredField<CreateCartParams, "customer_id">>,
  Assert<RequiredField<CreateCartParams, "sales_channel_id">>,
  Assert<Equal<CreateCartParams["catalog"], CartCatalogChoice>>,
  Assert<Equal<CartCatalogChoice["type"], "catalog" | "market_public">>,
  Assert<Missing<UpdateCartParams, "customer_id">>,
  Assert<RequiredField<UpdateCartParams, "expected_updated_at">>,
  Assert<Equal<FindCartsParams["statuses"], CartStatus["type"][] | undefined>>,
  Assert<Equal<FindCartsParams["origins"], CartOrigin["type"][] | undefined>>,
  Assert<Equal<FindCartsParams["sort_field"], "created_at" | "updated_at" | undefined>>,
  Assert<RequiredField<QuoteCartParams, "language">>,
  Assert<RequiredField<QuotePurchaseParams, "language">>,
  Assert<Equal<keyof StorefrontQuoteCartParams, "id" | "token">>,
  Assert<Missing<StorefrontQuoteCartParams, "language">>,
  Assert<Equal<Awaited<ReturnType<AdminCart["quote"]>>, CartQuote>>,
  Assert<Equal<CartQuote, Public.CartQuote>>,
  Assert<RequiredField<CartQuote, "presentation_digest">>,
  Assert<Equal<CartQuote["blockers"], QuoteBlocker[]>>,
  Assert<Equal<CartQuote["quoted_at"], EpochMilliseconds>>,
  Assert<Equal<QuoteMoney["type"], "taxed" | "awaiting_tax">>,
  Assert<RequiredField<QuoteShippingOffer, "shipping_method_key">>,
  Assert<RequiredField<QuoteShippingOffer, "shipping_method_blocks">>,
  Assert<RequiredField<QuoteShippingOffer, "free_shipping_applied">>,
  Assert<RequiredField<CheckoutCartParams, "presentation_digest">>,
  Assert<RequiredField<CheckoutCartParams, "language">>,
  Assert<RequiredField<CheckoutCartParams, "order_id">>,
  Assert<Missing<StorefrontCheckoutCartInput, "language">>,
  Assert<Equal<keyof StorefrontCheckoutCartInput, "order_id" | "cart_id" | "expected_updated_at" | "presentation_digest" | "contact_email" | "payment">>,
  Assert<Equal<CheckoutCartParams["payment"], CheckoutPaymentChoice>>,
  Assert<Equal<CheckoutPaymentChoice["type"], "free" | "payment_option" | "on_account">>,
  Assert<Equal<CheckoutAcceptance["type"], "placed" | "already_subscribed">>,
  Assert<Equal<Extract<CheckoutAcceptance, { type: "already_subscribed" }>, { type: "already_subscribed"; subscription_id: string }>>,
  Assert<Missing<StorefrontUpdateCartParams, "customer_id">>,
  Assert<Missing<StorefrontUpdateCartParams, "store_id">>,
  Assert<Missing<NonNullable<StorefrontUpdateCartParams["line_items"]>[number], "price_override">>,
  Assert<Missing<StorefrontAddCartProductParams["product"], "price_override">>,
  Assert<RequiredField<StorefrontAddCartProductParams["product"], "id">>,
  Assert<Equal<CartCheckoutRequest, StorefrontCheckoutCartInput>>,
  Assert<Missing<CartCheckoutRequest, "store_id">>,
  Assert<Equal<keyof ArkyCartCheckoutInput, "order_id" | "contact_email" | "payment" | "clear_after_checkout">>,
  Assert<RequiredField<ArkyCartCheckoutInput, "order_id">>,
  Assert<Equal<CartPresentationChangedError["quote"], CartQuote>>,
  Assert<Equal<Awaited<ReturnType<StorefrontCart["pendingCheckout"]>>, CartCheckoutRequest | null>>,
  Assert<Equal<Awaited<ReturnType<StorefrontCart["checkout"]>>, CheckoutAcceptance>>,
  Assert<Equal<Awaited<ReturnType<StorefrontCart["recoverCheckout"]>>, CheckoutAcceptance | null>>,
  Assert<Missing<StorefrontCart, "addDigital">>,
  Assert<Missing<AdminCart, "acceptFutureDeliveries">>,
];
